echo "utc=$(date -u +%FT%TZ) host=$(hostname)"
pid=$(ss -ltnpH 'sport = :30443' | grep -oE 'pid=[0-9]+' | head -1 | cut -d= -f2); port=$(ss -tnpH state established | grep "pid=$pid," | awk '$3 ~ /:22$/{print $4}' | sed 's/.*://' | head -1)
journalctl -q --no-pager -o short-iso-precise _COMM=sshd-session _COMM=sshd 2>/dev/null | grep -E "Accepted publickey for enclave-control-tunnel from [0-9.]+ port $port " | sed -E 's/^([^ ]+) [^ ]+ [^:]+: /\1 /' | tail -2 | sed 's/^/accept /'
h=$(getent passwd enclave-control-tunnel | cut -d: -f6); echo "tunnel_user_home=$h shell=$(getent passwd enclave-control-tunnel | cut -d: -f7)"
f="$h/.ssh/authorized_keys"; [ -r "$f" ] && { echo "authorized_keys sha16=$(sha256sum $f|cut -c1-16) lines=$(grep -cvE '^\s*(#|$)' $f)"; grep -vE '^\s*(#|$)' "$f" | while IFS= read -r l; do fp=$(echo "$l" | grep -oE '(ssh-ed25519|ssh-rsa|ecdsa-sha2-[a-z0-9]+) [A-Za-z0-9+/=]+.*' | ssh-keygen -lf - 2>/dev/null | awk '{print $1,$2,$NF}'); opts=$(echo "$l" | sed -E 's/ (ssh-ed25519|ssh-rsa|ecdsa-sha2-[a-z0-9]+) .*//' | grep -oE '(restrict|no-[a-z-]+|permitlisten="[^"]*"|permitopen="[^"]*"|from="[^"]*"|command)' | sed -E 's/^command$/command(set)/' | tr '\n' ' '); echo "  key bits/fp/type=$fp comment=$(echo "$l" | awk '{for(i=1;i<=NF;i++) if($i ~ /^(ssh-ed25519|ssh-rsa|ecdsa-sha2)/){c=""; for(j=i+2;j<=NF;j++) c=c" "$j; print c; break}}' | cut -c1-60) opts=$opts"; done; } || echo "authorized_keys unreadable_or_absent path=$f"
grep -rhoE '^\s*Match User enclave-control-tunnel|^\s*PermitListen .*|^\s*AllowTcpForwarding .*|^\s*GatewayPorts .*' /etc/ssh/sshd_config /etc/ssh/sshd_config.d/ 2>/dev/null | sed 's/^/sshd_cfg /'
